package rpg.engine.map;import org.junit.jupiter.api.*;import java.nio.file.*;import rpg.engine.core.math.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class RMapIOTest{@Test void roundTrip()throws Exception{var p=Files.createTempFile("test",".rmap");var m=new RMap("x",32,2,2,List.of(new TileLayer("g",2,2,new int[]{1,2,3,4},false)),List.of(new MapEntity("door","door",new WorldPosition(1,2,0),null)));RMapIO.write(m,p);var n=RMapIO.read(p);assertEquals(m.name(),n.name());assertArrayEquals(m.layers().get(0).tiles(),n.layers().get(0).tiles());assertEquals(m.entities().get(0).position(),n.entities().get(0).position());}}
